//! Checks of attribution against an independent NumPy implementation of the published formulas.
//! The fixture is generated by `scripts/reference/attribution.py`.

#![allow(clippy::unwrap_used)]

use finalytics_perf::*;
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/attribution.json")).unwrap()
}

fn floats(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect()
}

#[track_caller]
fn close(actual: f64, expected: f64, what: &str) {
    assert!(
        (actual - expected).abs() <= 1e-15 * expected.abs().max(1.0),
        "{what}: {actual} against the reference {expected}"
    );
}

#[track_caller]
fn close_all(actual: &[f64], expected: &[f64], what: &str) {
    assert_eq!(actual.len(), expected.len(), "{what}: lengths differ");
    for (k, (a, e)) in actual.iter().zip(expected).enumerate() {
        close(*a, *e, &format!("{what}[{k}]"));
    }
}

/// Linking coefficients divide by a difference of logarithms of returns that are close, so a
/// difference of one unit in the last place between two implementations of `log1p` becomes about
/// `1e-15` in a coefficient. The effects, which multiply the coefficients by small numbers, are
/// held to `1e-15`.
#[track_caller]
fn close_coefficients(actual: &[f64], expected: &[f64]) {
    assert_eq!(actual.len(), expected.len(), "coefficients: lengths differ");
    for (k, (a, e)) in actual.iter().zip(expected).enumerate() {
        assert!(
            (a - e).abs() <= 1e-13 * e.abs(),
            "coefficients[{k}]: {a} against the reference {e}"
        );
    }
}

fn effects(segments: &[SegmentEffects]) -> [Vec<f64>; 3] {
    [
        segments.iter().map(|s| s.allocation).collect(),
        segments.iter().map(|s| s.selection).collect(),
        segments.iter().map(|s| s.interaction).collect(),
    ]
}

#[test]
fn brinson_fachler_matches_the_reference() {
    let f = &fixture()["brinson_fachler"];
    let periods: Vec<AttributionPeriod> =
        serde_json::from_value(f["periods_input"].clone()).unwrap();
    for (linking, key) in [(Linking::Carino, "carino"), (Linking::Menchero, "menchero")] {
        let a = brinson_fachler(&periods, linking).unwrap();
        close(
            a.portfolio_return,
            f["portfolio_return"].as_f64().unwrap(),
            "portfolio",
        );
        close(
            a.benchmark_return,
            f["benchmark_return"].as_f64().unwrap(),
            "benchmark",
        );
        for (p, expected) in a.periods.iter().zip(f["periods"].as_array().unwrap()) {
            let [allocation, selection, interaction] = effects(&p.segments);
            close_all(
                &allocation,
                &floats(&expected["allocation"]),
                "period allocation",
            );
            close_all(
                &selection,
                &floats(&expected["selection"]),
                "period selection",
            );
            close_all(
                &interaction,
                &floats(&expected["interaction"]),
                "period interaction",
            );
        }
        let [allocation, selection, interaction] = effects(&a.segments);
        let reference = &f[key];
        let coefficients: Vec<f64> = a.periods.iter().map(|p| p.linking_coefficient).collect();
        close_coefficients(&coefficients, &floats(&reference["coefficients"]));
        close_all(&allocation, &floats(&reference["allocation"]), key);
        close_all(&selection, &floats(&reference["selection"]), key);
        close_all(&interaction, &floats(&reference["interaction"]), key);
        close(
            a.allocation + a.selection + a.interaction,
            a.excess_return,
            "effects add up",
        );
    }
}

fn currency_case(key: &str) {
    let f = &fixture()[key];
    let periods: Vec<CurrencyAttributionPeriod> =
        serde_json::from_value(f["periods_input"].clone()).unwrap();
    let a = karnosky_singer(&periods, Linking::Carino).unwrap();
    close(
        a.portfolio_return,
        f["portfolio_return"].as_f64().unwrap(),
        "portfolio",
    );
    close(
        a.benchmark_return,
        f["benchmark_return"].as_f64().unwrap(),
        "benchmark",
    );
    for (p, expected) in a.periods.iter().zip(f["periods"].as_array().unwrap()) {
        let [allocation, selection, _] = effects(&p.segments);
        close_all(
            &allocation,
            &floats(&expected["allocation"]),
            "market allocation",
        );
        close_all(
            &selection,
            &floats(&expected["selection"]),
            "market selection",
        );
        let currency: Vec<f64> = p.currencies.iter().map(|c| c.allocation).collect();
        close_all(&currency, &floats(&expected["currency"]), "currency");
        close(
            p.residual,
            expected["residual"].as_f64().unwrap(),
            "residual",
        );
    }
    let reference = &f["carino"];
    let coefficients: Vec<f64> = a.periods.iter().map(|p| p.linking_coefficient).collect();
    close_coefficients(&coefficients, &floats(&reference["coefficients"]));
    let currency: Vec<f64> = a.currencies.iter().map(|c| c.allocation).collect();
    close_all(
        &currency,
        &floats(&reference["currency"]),
        "linked currency",
    );
    close(
        a.residual,
        reference["residual"].as_f64().unwrap(),
        "linked residual",
    );
    let total = a.allocation + a.selection + a.interaction + a.currency + a.residual;
    close(total, a.excess_return, "effects add up");
}

#[test]
fn karnosky_singer_matches_the_reference() {
    currency_case("karnosky_singer");
}

#[test]
fn karnosky_singer_with_hedged_exposures_matches_the_reference() {
    currency_case("karnosky_singer_hedged");
    let f = &fixture()["karnosky_singer_hedged"];
    let periods: Vec<CurrencyAttributionPeriod> =
        serde_json::from_value(f["periods_input"].clone()).unwrap();
    let a = karnosky_singer(&periods, Linking::Menchero).unwrap();
    assert!(a.periods.iter().all(|p| p.residual.abs() < 1e-17));
}

#[test]
fn inputs_are_validated() {
    let f = &fixture()["karnosky_singer"];
    let mut periods: Vec<CurrencyAttributionPeriod> =
        serde_json::from_value(f["periods_input"].clone()).unwrap();
    periods[1].start = periods[0].start;
    periods[2]
        .currencies
        .retain(|c| c.currency != finalytics_core::Currency::JPY);
    let Err(finalytics_core::Error::Validation(report)) =
        karnosky_singer(&periods, Linking::Carino)
    else {
        panic!("expected a validation error");
    };
    let paths: Vec<&str> = report.issues().iter().map(|i| i.path.as_str()).collect();
    assert_eq!(
        paths,
        ["periods[1].start", "periods[2].segments[2].currency"]
    );
}
